/**
 * Block School course: the exercises of "BB School of Block – English"
 * (unofficial fan-made workbook by Ferns / Richard F. J., bbsob.net, free for
 * non-commercial use), Levels 1-7. Positions and questions come from the
 * workbook (src/courses/blockSchoolData.json, generated by
 * scripts/workbook/import_block_school.py); every answer and explanation shown
 * in the app is computed by the rules engine (rulebook pp.60-61, Guard p.129),
 * never copied from the workbook. Where the workbook's answer key and the
 * engine disagree, `discrepancy` says so (see docs/BLOCK_SCHOOL.md).
 */
import data from './blockSchoolData.json';

export type ExerciseKind = 'count' | 'moveOne' | 'normalMove' | 'blockFirst' | 'whoBlocks' | 'pushSquare';

export interface BlockSchoolExercise {
  id: string;
  level: number;
  number: number;
  /** Workbook page of the exercise and of its answer. */
  page: number;
  answerPage: number;
  question: string;
  kind: ExerciseKind;
  cells: Array<{ id: string; col: number; row: number }>;
  cols: number;
  rows: number;
  defaultST: number;
  strength: Record<string, number>;
  guard: string[];
  attacker: string;
  defender: string;
  workbookAnswer: string;
  /** Level 7: who may move (moveOne / normalMove). */
  movers?: string[];
  /** Level 7: who may make the first Block (blockFirst / whoBlocks / pushSquare). Empty = any X player except the attacker. */
  blockers?: string[];
  /** Level 7: restrict the first Block's target. */
  firstTargets?: string[];
  /** A difference between the workbook and the rules engine, in our words. */
  discrepancy?: string;
  hints: string[];
}

export interface BlockSchoolLevel {
  level: number;
  title: string;
  intro: string;
  rules: Array<{ page: number; title: string }>;
}

export const BLOCK_SCHOOL_SOURCE = 'BB School of Block – English (unofficial fan-made workbook by Ferns / Richard F. J., bbsob.net). Positions and questions are used for non-commercial training; explanations are generated from the Blood Bowl rulebook rules.';

export const LEVELS: BlockSchoolLevel[] = [
  { level: 1, title: 'One against one', intro: 'Compare the two players\' Strength. Equal Strength: 1 Block die. Stronger: 2 dice and the stronger side chooses the result. More than double: 3 dice.', rules: [{ page: 60, title: 'Block Actions' }] },
  { level: 2, title: 'Offensive assists', intro: 'Each other attacking player who Marks the defender adds +1 to the attacker\'s Strength — but only if no opposition player other than the defender is Marking that helper.', rules: [{ page: 61, title: 'Assists' }] },
  { level: 3, title: 'Defensive assists', intro: 'The defender\'s team-mates who Mark the attacker help the same way: +1 each, unless an attacking player other than the blocker is Marking them.', rules: [{ page: 61, title: 'Assists' }] },
  { level: 4, title: 'Different Strengths', intro: 'Now the players\' Strength varies. Add the assists to each player\'s own Strength before comparing.', rules: [{ page: 60, title: 'Block Actions' }] },
  { level: 5, title: 'Guard', intro: 'A player with Guard can assist even while other opposition players are Marking them. They still have to Mark the player they help against.', rules: [{ page: 129, title: 'Guard' }, { page: 61, title: 'Assists' }] },
  { level: 6, title: 'Putting it together', intro: 'Strength differences, Guard on both sides and crowded scrums: count every helper carefully.', rules: [{ page: 60, title: 'Block Actions' }, { page: 61, title: 'Assists' }, { page: 129, title: 'Guard' }] },
  { level: 7, title: 'Preparing the block', intro: 'Before the key Block, a move or another Block can change who is free to assist. Find the preparation that gives X1 a 2-dice Block.', rules: [{ page: 61, title: 'Assists' }, { page: 62, title: 'Pushed Back / Follow-up' }] },
];

const COUNT_HINTS = [
  'Start with each player\'s own Strength (ST).',
  'Look at every X player next to the defender. Is an opposition player other than the defender Marking them? If so they cannot help — unless they have Guard.',
  'Do the same for the Y players next to the attacker (ignore the attacker itself when checking who Marks them).',
  'Compare the totals: equal → 1 die; higher → 2 dice; more than double → 3 dice. The stronger side chooses.',
];

const L7: Record<string, Partial<BlockSchoolExercise>> = {
  L7E1: { kind: 'normalMove', movers: ['X2'], discrepancy: 'The answer key describes moving X2 from A3 to B3, but the printed diagram already shows X2 on B3, so X1\'s Block is already 2D (ST 5 v 3). The app keeps the printed position: leaving X2 where it is (or any square where the count stays 2D) is accepted.' },
  L7E2: { kind: 'blockFirst', blockers: ['X3'] },
  L7E3: { kind: 'blockFirst', blockers: ['X2'], discrepancy: 'The engine also accepts Y3: if X2\'s Block knocks Y3 down (knocked down into A4, or Both Down), X4 is free to assist. Blocking Y2 (the workbook answer) works with any push.' },
  L7E4: { kind: 'moveOne', movers: ['X2', 'X4'], discrepancy: 'In the printed diagram X1\'s Block is already 2D before any move (X3 assists with Guard: ST 4 v 3), so several one-square moves keep it 2D; the workbook answer (X4 to B4) is one of them.' },
  L7E5: { kind: 'moveOne', movers: ['X2'], discrepancy: 'In the printed diagram X2 on B4 is already diagonally next to Y1 and unmarked, so X1\'s Block is already 2D; the workbook answer (B3) keeps it 2D.' },
  L7E6: { kind: 'normalMove', movers: ['X2'], discrepancy: 'As the answer key itself notes, X3 already assists with Guard, so the Block is 2D before X2 moves; most squares keep it 2D.' },
  L7E7: { kind: 'moveOne', movers: ['X2'], discrepancy: 'The engine finds a second correct square: E4 also Marks Y2 and gives 2D, as well as the workbook\'s D4.' },
  L7E8: { kind: 'moveOne', movers: ['X2'], discrepancy: 'In the printed diagram X2 on E2 already Marks Y2, so Y2 cannot assist and X1\'s Block is already 2D. The workbook answer E3 keeps it 2D; D2 does too.' },
  L7E9: { kind: 'moveOne', movers: ['X2'], discrepancy: 'The question says the Block is −2D because Y2 assists Y1, but in the printed diagram X2 (Guard) on D2 already Marks Y2 and assists X1, so the Block is already 2D; the workbook answer C2 keeps it 2D.' },
  L7E10: { kind: 'blockFirst', blockers: ['X2'], discrepancy: 'The answer (Y2) is right, but the key\'s count (Y3 cannot assist, ST 4 v 3) only holds if X2 follows up into C2 and Marks Y3. Without the follow-up X2 assists too and Y3 still helps Y1: ST 5 v 4, which is also 2D.' },
  L7E11: { kind: 'whoBlocks', blockers: ['X2', 'X4'], discrepancy: 'The key\'s explanation says X4 Marks Y3, but in the printed diagram X4 (B4) is not next to Y3 (D3). X2 blocking Y2 is still right: without a follow-up it is ST 5 v 4, with a follow-up into C2 it is ST 4 v 3 — 2D either way.' },
  L7E12: { kind: 'whoBlocks', blockers: ['X2', 'X4'] },
  L7E13: { kind: 'blockFirst', blockers: [], discrepancy: 'Exercises 13 and 14 show the same position. The engine also accepts Y3: X4 pushing Y3 into D2 or E2 without following up frees X4 to assist (ST 4 v 3).' },
  L7E14: { kind: 'blockFirst', blockers: [], firstTargets: ['Y2', 'Y3'], discrepancy: 'Exercises 13 and 14 show the same position. The engine also accepts Y3: X4 pushing Y3 into D2 or E2 without following up frees X4 to assist (ST 4 v 3). Blocking Y2 frees two helpers (X2 and X3), so it is the more robust choice.' },
  L7E15: { kind: 'pushSquare', blockers: ['X2'], firstTargets: ['Y2'], discrepancy: 'The engine finds a second push square: D2 also gives 2D, as well as the workbook\'s D1.' },
};

const L7_HINTS: Record<string, string[]> = {
  moveOne: ['Count X1\'s Block as it stands first.', 'Which helper is blocked from assisting, and by whom? Which opponent is helping Y1?', 'A move can give a new assist (Mark Y1 while unmarked) or cancel a defensive assist (Mark the Y helper).'],
  normalMove: ['Count X1\'s Block as it stands first.', 'X2 can go anywhere it can reach with a normal Move; think about which square both Marks Y1 and is free of other opponents — or ties up a Y helper.'],
  blockFirst: ['Which opponent is stopping an X assist or helping Y1?', 'If that opponent is knocked down, or pushed out of the way, who becomes free?', 'Remember the push direction and the optional follow-up: where the blocker ends matters too.'],
  whoBlocks: ['Try each candidate Block in your head: after it, who Marks whom?', 'A good first Block removes the opponent that is cancelling an X assist.'],
  pushSquare: ['List the squares Y2 can be pushed into.', 'After the push, is Y2 still Marking an X helper, or still next to X1?'],
};

const DUPLICATE: Record<string, string> = { L2E3: 'Exercises 2 and 3 of Level 2 show the same position.', L2E2: 'Exercises 2 and 3 of Level 2 show the same position.' };

type Raw = (typeof data)['exercises'][number];

export const EXERCISES: BlockSchoolExercise[] = (data.exercises as Raw[]).map((e) => {
  const extra = L7[e.id] ?? {};
  const kind = (extra.kind ?? 'count') as ExerciseKind;
  return {
    id: e.id,
    level: e.level,
    number: e.number,
    page: e.page,
    answerPage: e.answerPage,
    question: e.question,
    kind,
    cells: e.cells,
    cols: e.cols,
    rows: e.rows,
    defaultST: e.defaultST,
    strength: e.strength as Record<string, number>,
    guard: e.guard,
    attacker: e.attacker,
    defender: e.defender,
    workbookAnswer: e.workbookAnswer,
    movers: extra.movers,
    blockers: extra.blockers,
    firstTargets: extra.firstTargets,
    discrepancy: extra.discrepancy ?? DUPLICATE[e.id],
    hints: kind === 'count' ? COUNT_HINTS : L7_HINTS[kind] ?? [],
  };
});

export const EXERCISE_BY_ID: Record<string, BlockSchoolExercise> = Object.fromEntries(EXERCISES.map((e) => [e.id, e]));
